"""
Invoice export to the billing API (written against pydantic 1.10).

Provides:
  - export_invoice(data: dict) -> str
"""
from __future__ import annotations

from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, List

from pydantic import BaseModel, ValidationError, validator
from pydantic.json import ENCODERS_BY_TYPE


def _to_utc_datetime(value: datetime) -> datetime:
    """Convert naive datetimes to UTC; convert aware datetimes to UTC."""
    if value.tzinfo is None or value.tzinfo.utcoffset(value) is None:
        return value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc)


def _format_issued_at_utc_z(dt: datetime) -> str:
    """YYYY-MM-DDTHH:MM:SSZ in UTC (second precision)."""
    dt_utc = _to_utc_datetime(dt)
    return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")


def _quantize_2dp(d: Decimal) -> Decimal:
    # Convert to exactly 2 decimal places (billing API expects that exact form)
    return d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


class InvoiceLine(BaseModel):
    sku: str
    quantity: int
    unit_price: Decimal

    @validator("quantity")
    def quantity_min_1(cls, v: int) -> int:
        if v < 1:
            raise ValueError("quantity must be >= 1")
        return v

    @validator("unit_price", pre=True)
    def unit_price_non_negative(cls, v: Any) -> Any:
        # Let pydantic parse into Decimal; then validate constraints in a second validator.
        return v

    @validator("unit_price")
    def unit_price_constraints(cls, v: Decimal) -> Decimal:
        if v < 0:
            raise ValueError("unit_price must be >= 0")
        # Ensure it is representable with at most 2 decimal places; then quantize.
        quantized = _quantize_2dp(v)
        if v != quantized:
            # Reject inputs with more than 2 decimals to avoid silently rounding.
            raise ValueError("unit_price must have at most 2 decimal places")
        return quantized


class InvoiceExportModel(BaseModel):
    number: str
    issued_at: datetime
    lines: List[InvoiceLine]

    class Config:
        # We'll custom-encode issued_at with required format for the billing API.
        json_encoders = {
            datetime: _format_issued_at_utc_z,
            Decimal: lambda d: f"{_quantize_2dp(d):.2f}",
        }

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, v: Any) -> Any:
        # pydantic parses ISO strings already; we only need to ensure timezone handling later.
        return v

    @validator("issued_at")
    def issued_at_to_utc(cls, v: datetime) -> datetime:
        return _to_utc_datetime(v)

    def export_dict(self) -> dict:
        total = sum((line.quantity * line.unit_price for line in self.lines), Decimal("0"))
        total_q = _quantize_2dp(total)

        return {
            "number": self.number,
            "issued_at": _format_issued_at_utc_z(self.issued_at),
            "lines": [
                {
                    "sku": line.sku,
                    "quantity": line.quantity,
                    # Exactly two decimals as a string
                    "unit_price": f"{_quantize_2dp(line.unit_price):.2f}",
                }
                for line in self.lines
            ],
            # Total is required as a string with exactly two decimals
            "total": f"{total_q:.2f}",
        }


def export_invoice(data: dict) -> str:
    """
    Validate invoice input and return billing-API JSON text.

    Expected input:
      - number (str)
      - issued_at (ISO 8601 string or datetime; naive values treated as UTC)
      - lines: list of dicts with
          - sku (str)
          - quantity (int >= 1)
          - unit_price (Decimal >= 0; provided as str/int/float)

    Output JSON:
      - number
      - issued_at: "YYYY-MM-DDTHH:MM:SSZ"
      - lines: [{"sku", "quantity", "unit_price"}] where unit_price is a string with exactly 2 decimals
      - total: string with exactly 2 decimals (sum(quantity * unit_price))

    Raises ValueError for invalid input.
    """
    try:
        model = InvoiceExportModel.parse_obj(data)
    except ValidationError as e:
        # Callers rely on ValueError semantics for invalid inputs.
        raise ValueError(str(e)) from e

    # Produce JSON with the exact required shapes/encodings.
    # Use BaseModel's JSON utilities for consistent formatting.
    # But we must ensure unit_price/total formatting is exact strings with 2 decimals.
    payload = model.export_dict()
    return BaseModel.parse_obj(payload).json()  # not suitable for exact structure typing

from __future__ import annotations

from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP, InvalidOperation
from typing import Any, Dict, List, Optional

from pydantic import BaseModel, Field, ValidationError, field_validator


_DECIMAL_2 = Decimal("0.01")


def _to_decimal_2(value: Any, *, allow_zero: bool = True) -> Decimal:
    """
    Convert input to Decimal safely and quantize to 2 decimal places.
    - For floats, use str(value) to reduce binary artifacts compared to Decimal(value).
    """
    if isinstance(value, Decimal):
        dec = value
    elif isinstance(value, float):
        dec = Decimal(str(value))
    elif isinstance(value, int):
        dec = Decimal(value)
    elif isinstance(value, str):
        try:
            dec = Decimal(value)
        except InvalidOperation as e:
            raise ValueError("invalid decimal") from e
    else:
        raise ValueError("invalid decimal")

    if not allow_zero and dec <= 0:
        raise ValueError("value must be greater than 0")

    # Quantize to exactly 2 decimals for output stability.
    try:
        return dec.quantize(_DECIMAL_2, rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError) as e:
        raise ValueError("invalid decimal precision") from e


def _format_issued_at_utc(value: datetime) -> str:
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    else:
        value = value.astimezone(timezone.utc)

    # Required format: YYYY-MM-DDTHH:MM:SSZ (UTC)
    return value.replace(microsecond=0).strftime("%Y-%m-%dT%H:%M:%SZ")


class InvoiceLine(BaseModel):
    sku: str
    quantity: int = Field(..., ge=1)
    unit_price: Decimal

    # Coerce/validate unit_price
    @field_validator("unit_price", mode="before")
    @classmethod
    def parse_unit_price(cls, v: Any) -> Decimal:
        dec = _to_decimal_2(v, allow_zero=True)
        if dec < 0:
            raise ValueError("unit_price must be >= 0")
        return dec

    class Config:
        extra = "forbid"


class Invoice(BaseModel):
    number: str
    issued_at: datetime
    lines: List[InvoiceLine]

    @field_validator("issued_at", mode="before")
    @classmethod
    def parse_issued_at(cls, v: Any) -> datetime:
        # Let pydantic parse ISO strings, but ensure naive datetimes are treated as UTC.
        # If it's already a datetime, accept it.
        if isinstance(v, datetime):
            return v
        if isinstance(v, str):
            # pydantic will parse ISO 8601; return as-is for pydantic to convert
            return v
        raise ValueError("issued_at must be an ISO 8601 string or datetime")

    @field_validator("lines", mode="before")
    @classmethod
    def parse_lines(cls, v: Any) -> Any:
        if not isinstance(v, list):
            raise ValueError("lines must be a list")
        return v

    def to_billing_payload(self) -> Dict[str, Any]:
        total = Decimal("0")
        for line in self.lines:
            total += (line.unit_price * Decimal(line.quantity))

        total = total.quantize(_DECIMAL_2, rounding=ROUND_HALF_UP)

        return {
            "number": self.number,
            "issued_at": _format_issued_at_utc(self.issued_at),
            "lines": [
                {
                    "sku": line.sku,
                    "quantity": line.quantity,
                    "unit_price": f"{line.unit_price:.2f}",
                }
                for line in self.lines
            ],
            "total": f"{total:.2f}",
        }

    class Config:
        extra = "forbid"


def export_invoice(data: dict) -> str:
    """
    Validate an invoice and return its JSON text for the billing API.

    Expected input:
      - number (str)
      - issued_at (ISO 8601 string or datetime; naive treated as UTC)
      - lines: list of { sku: str, quantity: int>=1, unit_price: decimal>=0 as str/int/float }

    Output JSON:
      - number
      - issued_at formatted "YYYY-MM-DDTHH:MM:SSZ" in UTC
      - lines: each { sku, quantity, unit_price } where unit_price is a string with exactly 2 decimals
      - total: sum(quantity * unit_price) as a string with exactly 2 decimals

    Raises ValueError for invalid input.
    """
    try:
        invoice = Invoice.model_validate(data)
    except ValidationError as e:
        # pydantic ValidationError is a ValueError subclass in v2, but normalize to meet the contract.
        raise ValueError(str(e)) from e

    payload = invoice.to_billing_payload()
    # Deterministic JSON formatting: keys in insertion order (Python 3.11 preserves dict order).
    # Use default separators for compact output.
    import json

    return json.dumps(payload, ensure_ascii=False, separators=(",", ":"))

from __future__ import annotations

from typing import Any, Dict, List

from pydantic import ValidationError

from profile_models import Profile


def import_profiles(rows: list) -> list:
    """
    Validate imported profile rows (dicts) and return only the valid ones as dicts:
    {"user_id": int, "display_name": str, "bio": str|None, "zip_code": str}

    Invalid rows are silently skipped. Output order matches input order.
    """
    valid: List[Dict[str, Any]] = []

    for row in rows:
        try:
            profile = Profile.model_validate(row)
        except (ValidationError, ValueError, TypeError):
            continue

        valid.append(
            {
                "user_id": profile.user_id,
                "display_name": profile.display_name,
                "bio": profile.bio,
                "zip_code": profile.zip_code,
            }
        )

    return valid
